// Package moshihooks ports /root/.pi/agent/extensions/moshi-hooks.ts (836 lines,
// generated by /root/.local/bin/moshi-hook) to PiG's Go extension SDK.
//
// The TypeScript file normalizes Pi's lifecycle events and writes each one as a
// single JSON line to the moshi-hook daemon socket (a named pipe on Windows) —
// no per-event helper spawn. When the daemon is absent the connect fails
// silently and the turn is never interrupted. This port keeps that contract:
// every failure path is silent, every envelope is delivered in order, and the
// session_shutdown handler still waits up to one second for the queue to drain.
//
// Line-for-line mapping to the source, and the few places where the PiG SDK has
// no equivalent host accessor, are documented in README.md.
package moshihooks

import (
	"math"
	"sync"

	sdk "github.com/MichaelKinsy/PiG/extensions/sdk"
)

// helperBinary is the CLI adapter the TS keeps for debugging / manual replay
// (`moshi-hook pi-hook`). The extension never spawns it (TS L16).
const helperBinary = "/root/.local/bin/moshi-hook"

// sdk call shape: every accessor below tolerates a replaced or reloaded
// session. The SDK's Context panics on a stale session, and a hook must never
// interrupt the turn, so each read is guarded and degrades to the TS's `""`.

// safeCwd reads ctx.cwd (TS: `ctxObj.cwd`).
func safeCwd(ctx sdk.Context) (value string) {
	defer func() { _ = recover() }()
	return ctx.Cwd()
}

// safeModelID reads ctx.model.id.
func safeModelID(ctx sdk.Context) (value string) {
	defer func() { _ = recover() }()
	return ctx.Model()
}

// safeSessionID reads sessionManager.getSessionId().
func safeSessionID(ctx sdk.Context) (value string) {
	defer func() { _ = recover() }()
	id, err := ctx.SessionManager().GetSessionID()
	if err != nil {
		return ""
	}
	return id
}

// safeSessionFile reads sessionManager.getSessionFile(); an in-memory session
// has none. It is level 1 of the four-level transcriptPath chain
// (TS pig: transcriptPath).
func safeSessionFile(ctx sdk.Context) (value string) {
	defer func() { _ = recover() }()
	file, err := ctx.SessionManager().GetSessionFile()
	if err != nil || file == nil {
		return ""
	}
	return *file
}

// modelLabelForCtx is `modelLabel(ctx.model)` (TS L774). The SDK exposes the
// active model as structured metadata, whose display name and id are the two
// fields modelLabel would pick first; the bare model id is the fallback.
func modelLabelForCtx(ctx sdk.Context) (label string) {
	defer func() { _ = recover() }()
	if info, err := ctx.GetModelInfo(); err == nil && info != nil {
		return modelLabel(map[string]any{"name": info.Name, "id": info.ID})
	}
	return firstString(safeModelID(ctx))
}

// contextRemainingFrom is contextRemaining(ctx) (TS L288): the share of the
// context window still free, rounded and clamped to [1, 100], or absent when
// the host reports no usable usage.
func contextRemainingFrom(ctx sdk.Context) (remaining *float64) {
	defer func() { _ = recover() }()
	usage, err := ctx.GetContextUsage()
	if err != nil || usage == nil || usage.Percent == nil {
		return nil
	}
	percent := *usage.Percent
	if math.IsNaN(percent) || math.IsInf(percent, 0) {
		return nil
	}
	value := math.Max(1, math.Min(100, math.Round(100-percent)))
	return &value
}

// agentKind mirrors ctx.agent.kind (TS: agentKind, L769). The PiG SDK exposes
// no agent accessor, so the value is read from the event payload when the host
// provides one. With agentSource "pi" sessionIsChild never consults it, so the
// generated-for-Pi behavior of the TS is preserved exactly.
func agentKind(event map[string]any) string {
	return firstString(event["agent_kind"], event["agentKind"])
}

// sessionID reads the session identity, preferring the host's session manager
// (TS: sessionID, L260).
func sessionID(event map[string]any, ctx sdk.Context) string {
	return firstString(safeSessionID(ctx), event["session_id"], event["sessionId"], "pi")
}

// Send normalizes one host event and hands it to handleEvent
// (TS: send, L774). A normalization failure is swallowed: hooks should never
// interrupt the user's Pi turn.
func Send(eventName string, event map[string]any, ctx sdk.Context, extra map[string]any) {
	defer func() { _ = recover() }()

	id := sessionID(event, ctx)
	cwd := firstString(safeCwd(ctx), processCwd())
	payload := &HookPayload{
		HookEventName:    eventName,
		SessionID:        id,
		TranscriptPath:   resolveTranscriptPath(safeSessionFile(ctx), event, id, cwd),
		Cwd:              cwd,
		Model:            modelLabelForCtx(ctx),
		ContextRemaining: contextRemainingFrom(ctx),
		AgentKind:        agentKind(event),
		Extra:            extra,
	}
	handleEvent(payload, event)
}

// lastAssistantMessage carries the text agent_end remembered for the
// agent_settled event that follows it (TS: the `lastAssistantMessage` closure
// variable, L802-812).
type lastAssistantMessage struct {
	mu   sync.Mutex
	text string
}

func (m *lastAssistantMessage) set(text string) {
	m.mu.Lock()
	m.text = text
	m.mu.Unlock()
}

func (m *lastAssistantMessage) take() string {
	m.mu.Lock()
	defer m.mu.Unlock()
	text := m.text
	m.text = ""
	return text
}

// lastAssistantMessageIn scans messages backwards for the last assistant
// message and returns its text (TS: the agent_end loop, L805-812). found is
// false when the turn has no assistant message, in which case the previously
// remembered text stays.
func lastAssistantMessageIn(messages any) (text string, found bool) {
	list, ok := messages.([]any)
	if !ok {
		return "", false
	}
	for index := len(list) - 1; index >= 0; index -= 1 {
		message, ok := list[index].(map[string]any)
		if !ok {
			continue
		}
		if role, _ := message["role"].(string); role == "assistant" {
			return textFromMessage(message), true
		}
	}
	return "", false
}

// Extension constructs and returns the moshi-hooks extension for PiG.
//
// The registered hooks are the six the TS registers (L795-836): session_start,
// before_agent_start, agent_start, agent_end (remember only), agent_settled and
// session_shutdown.
func Extension() *sdk.Extension {
	e := sdk.New("moshi-hooks")

	remembered := &lastAssistantMessage{}

	e.OnEvent(sdk.EventSessionStart, func(ctx sdk.Context, event map[string]any) (any, error) {
		Send("SessionStart", event, ctx, nil)
		return nil, nil
	})

	e.OnEvent(sdk.EventBeforeAgentStart, func(ctx sdk.Context, event map[string]any) (any, error) {
		Send("UserPromptSubmit", event, ctx, map[string]any{"prompt": event["prompt"]})
		return nil, nil
	})

	e.OnEvent(sdk.EventAgentStart, func(ctx sdk.Context, event map[string]any) (any, error) {
		Send("AgentStart", event, ctx, nil)
		return nil, nil
	})

	// agent_end fires after each low-level run; Pi may still retry, compact or
	// continue with queued follow-ups, so only the settled event publishes.
	e.OnEvent(sdk.EventAgentEnd, func(_ sdk.Context, event map[string]any) (any, error) {
		if text, found := lastAssistantMessageIn(event["messages"]); found {
			remembered.set(text)
		}
		return nil, nil
	})

	e.OnEvent(sdk.EventAgentSettled, func(ctx sdk.Context, event map[string]any) (any, error) {
		Send("AgentEnd", event, ctx, map[string]any{"last_assistant_message": remembered.take()})
		return nil, nil
	})

	// The host awaits this handler before exiting, which is what the TS's
	// returned flushSends(1000) promise does: without it the process exits
	// before the socket even connects and the session never ends in Moshi.
	e.OnEvent(sdk.EventSessionShutdown, func(ctx sdk.Context, event map[string]any) (any, error) {
		Send("SessionEnd", event, ctx, nil)
		FlushSends(ShutdownFlushTimeout)
		return nil, nil
	})

	return e
}
